10: - name: letsencrpyt acme challenge proxing
11:   hosts: ofn_servers
12:   remote_user: "{{ user }}"
13: 
14:   vars:
15:     nginx_acme_challenge_config: |+
16:       location '/.well-known/acme-challenge' {
17:         # Temporary proxy of letencrypt certificate validation checks
18:         proxy_pass http://{{ proxy_target }}/.well-known/acme-challenge;
19:         proxy_set_header    Host            $host;
20:         proxy_set_header    X-Real-IP       $remote_addr;
21:         proxy_set_header    X-Forwarded-for $remote_addr;
22:         port_in_redirect off;
23:         proxy_connect_timeout 300;
24:       }
