37:       # Suspend
38:       - flux --namespace {{.NS}} suspend kustomization {{.APP}}
39:       - flux --namespace {{.NS}} suspend helmrelease {{.APP}}
40:       - kubectl --namespace {{.NS}} scale {{.CONTROLLER}}/{{.APP}} --replicas 0
41:       - kubectl --namespace {{.NS}} wait pod --for=delete --selector="app.kubernetes.io/name={{.APP}}" --timeout=5m
42:       # Restore, in place, into the existing PVC (no PVC recreation needed)
43:       - >-
44:         kubectl kopiur restore --from-policy {{.APP}}
45:         {{if .AS_OF}}--as-of {{.AS_OF}}{{end}}
46:         --on-missing-snapshot fail
47:         --to-pvc {{.APP}} -n {{.NS}} --wait
48:       # Resume
49:       - flux --namespace {{.NS}} resume kustomization {{.APP}}
50:       - flux --namespace {{.NS}} resume helmrelease {{.APP}}
51:       - flux --namespace {{.NS}} reconcile helmrelease {{.APP}} --force
52:       - kubectl --namespace {{.NS}} wait pod --for=condition=ready --selector="app.kubernetes.io/name={{.APP}}" --timeout=5m
